  ('eritromicina', 'Eritromicina', 'Erythromycin', 'Macrólido bacteriostático', 'Bacteriostatic macrolide', ARRAY['Eritrocina', 'Erythrocin'], 'published', 76),
  ('levofloxacina', 'Levofloxacina', 'Levofloxacin', 'Quinolona (fluorquinolona) de largo espetro', 'Broad-spectrum fluoroquinolone', ARRAY['Tavanic', 'Levaquin'], 'published', 77),
  ('moxifloxacina', 'Moxifloxacina', 'Moxifloxacin', 'Quinolona (fluorquinolona) de largo espetro', 'Broad-spectrum fluoroquinolone', ARRAY['Avalox', 'Avelox'], 'published', 78),
  ('metronidazol', 'Metronidazol', 'Metronidazole', 'Antibacteriano/antiparasitário (nitroimidazol)', 'Antibacterial/antiparasitic (nitroimidazole)', ARRAY['Flagyl'], 'published', 79),
  ('vancomicina', 'Vancomicina', 'Vancomycin', 'Glicopéptido ativo contra gram+ (incl. MRSA)', 'Glycopeptide active against gram+ (incl. MRSA)', ARRAY['Vancocina', 'Vancocin'], 'published', 80),
  ('daptomicina', 'Daptomicina', 'Daptomycin', 'Lipopéptido cíclico (gram+ multirresistentes)', 'Cyclic lipopeptide (multidrug-resistant gram+)', ARRAY['Cubicin'], 'published', 81),
  ('fosfomicina', 'Fosfomicina', 'Fosfomycin trometamol', 'Derivado do ácido fosfónico (infeções urinárias)', 'Phosphonic acid derivative (urinary tract)', ARRAY['Monuril'], 'published', 82);

INSERT INTO public.drug_interactions
  (drug_a_id, drug_b_id, severity, summary_pt, summary_en, mechanism_pt, mechanism_en,
   management_pt, management_en, monitoring_pt, monitoring_en, red_flags_pt, red_flags_en,
